"""
naist-jdic.csv と unidic-csj.csv の既存エントリのアクセント欄の修正表。

件数が多いため modify_dictionary.py から切り出している。
キーは FIELD_FIXES (表層, 文脈 ID, 原形, 読み) と UNIDIC_FIELD_FIXES (表層, 文脈 ID, 読み) と同じで、原形と読みのコロンは除く。
文脈 ID が "*" の項目は、表層・原形・読みが同じすべての文脈 ID の行に当たる (文脈 ID を指定した項目があればそちらを優先する)。
値は列番号から書き換え後の値への対応で、アクセント句を分ける行だけが原形・読み・発音の列も書き換える。
"""

